import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;

public class SecureFileAccess {
    public static void main(String[] args) {
        String userInput = request.getParameter("filename");

        // First, resolve the canonical path to prevent symbolic links and relative path tricks
        File baseDir = new File("/safe/directory").getCanonicalFile();
        File requestedFile = new File(baseDir, userInput).getCanonicalFile();

        // Ensure the resolved file is strictly within the allowed base directory
        if (!requestedFile.getPath().startsWith(baseDir.getPath())) {
            throw new SecurityException("Invalid file path: Access denied");
        }

        try {
            byte[] data = Files.readAllBytes(Paths.get(requestedFile.getAbsolutePath()));
            System.out.println(new String(data));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
